import{_ as a,c as e,o as s,a4 as t}from"./chunks/framework.4aTu-Nia.js";const m=JSON.parse('{"title":"HTTP","description":"","frontmatter":{},"headers":[],"relativePath":"web/http.md","filePath":"web/http.md"}'),n={name:"web/http.md"},l=t(`<h1 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#浏览器缓存">浏览器缓存</a><ul><li><a href="#缓存最佳策略">缓存最佳策略</a></li><li><a href="#缓存有效期计算">缓存有效期计算</a></li><li><a href="#内存缓存">内存缓存</a></li></ul></li><li><a href="#https">HTTPS</a></li><li><a href="#cors">CORS</a></li><li><a href="#返回状态码">返回状态码</a></li><li><a href="#get-与-post-区别">GET 与 POST 区别</a><ul><li><a href="#get-url-长度限制">get url 长度限制</a></li></ul></li><li><a href="#请描述-cookies、sessionstorage-和-localstorage-的区别">请描述 cookies、sessionStorage 和 localStorage 的区别?</a></li><li><a href="#http-与-tcp-区别">http 与 tcp 区别</a></li><li><a href="#dns">DNS</a></li><li><a href="#tcp">TCP</a></li><li><a href="#etag-和-last-modified-区别-使用场景">Etag 和 Last-Modified 区别，使用场景</a></li><li><a href="#expires-和-cache-control">Expires 和 Cache-Control</a></li><li><a href="#加密">加密</a></li><li><a href="#幂等性">幂等性</a></li><li><a href="#常用-code">常用 code</a></li><li><a href="#form-urlencoded">form-urlencoded</a></li></ul></nav><p><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Connection_management_in_HTTP_1.x" target="_blank" rel="noreferrer">Connection management in HTTP/1.x - HTTP | MDN</a></p><p>名词： ETag 文件指纹，如 content hash</p><h2 id="浏览器缓存" tabindex="-1">浏览器缓存 <a class="header-anchor" href="#浏览器缓存" aria-label="Permalink to &quot;浏览器缓存&quot;">​</a></h2><p>http cache 设计原则</p><p>默认隐式，显式用 cache-control</p><p>请求和响应，都能带指令，有冲突时，以更严格为准</p><p>两种模型：</p><ol><li><p>过期模型，减少频繁请求网络往返 Expires Cache-Control max-age 优先级高于上者</p></li><li><p>验证模型，减少带宽开销 条件请求 Last-Modified 默认弱验证 Etag 默认强验证</p><p>建议同时提供 Etag 和 LM 前者文件一变就变，后者在发生有意义变化时变</p></li></ol><p>启发式过期，慎用，建议明确指定</p><p>如何比对 ETag 和 LM，请求时带上之前的，即 If-xxx</p><p>流程：是否命中强缓存 -&gt; 是否命中协商缓存</p><p><a href="https://www.w3.org/Protocols/rfc2616/rfc2616-sec13.html#sec13.1.5" target="_blank" rel="noreferrer">HTTP/1.1: Caching in HTTP</a></p><ul><li><p>强缓存<code>header -&gt; max, cache</code>命中时不发网络请求</p></li><li><p>协商缓存<code>header -&gt; modifier</code>先发请求，命中 返回 304</p><p><code>no-cache</code> = store + if change 如果存在合适的验证令牌(ETag)，发起请求，如果资源无变化，304，不下载</p><p><code>no-store</code> 完全不存储，如私密文件</p></li><li><p>刷新(F5)，跳过强缓存，但是会检查协商缓存（协商缓存本身已经是一种避免内容不更新的策略，没必要跳过强刷）</p></li><li><p>强制刷新(Ctrl + F5)，跳过强缓存和协商缓存</p><p><a href="https://www.cnblogs.com/lyzg/p/5125934.html" target="_blank" rel="noreferrer">浏览器缓存知识小结及应用 - 流云诸葛 - 博客园</a></p><p><a href="https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/http-caching?hl=zh-cn" target="_blank" rel="noreferrer">HTTP 缓存  |  Web  |  Google Developers</a></p><p><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">HTTP caching - HTTP | MDN</a></p></li><li><p>不设置</p><ul><li>跳转访问 size 列 显示 disk cache 或请求详情 General 显示 Status Code: 200 OK (from disk cache)</li><li>直接打开资源链接，chrome 会在请求头加上<code>max-age=0</code>，走协商缓存 显示 304，不需要再接收响应体，节省一些带宽</li><li>浏览器缓存策略有差异，所以不需要缓存时，最好显式指定</li></ul></li><li><p>共享代理缓存 VS 私人浏览器缓存</p><p>共享缓存可以存在中间服务器上（只是个概念，如 cdn）</p></li></ul><h3 id="缓存最佳策略" tabindex="-1">缓存最佳策略 <a class="header-anchor" href="#缓存最佳策略" aria-label="Permalink to &quot;缓存最佳策略&quot;">​</a></h3><ul><li>For html files, use Cache-Control: no-cache, and Etag. 协商缓存</li><li>For js,css, and image files, set Cache-Control: public, max-age=31536000, no Etag, no Last-Modified settings. 强缓存，因为新资源 URL 一般有版本</li></ul><h3 id="缓存有效期计算" tabindex="-1">缓存有效期计算 <a class="header-anchor" href="#缓存有效期计算" aria-label="Permalink to &quot;缓存有效期计算&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>// freshnessLifetime</span></span>
<span class="line"><span>if \`Cache-control: max-age=N\` exist</span></span>
<span class="line"><span>  = N</span></span>
<span class="line"><span>else if \`Expires\` exist</span></span>
<span class="line"><span>  = Expires - Date</span></span>
<span class="line"><span>else if \`Last-Modified\` exist</span></span>
<span class="line"><span>  = (Date - Last-Modified) / 10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>expirationTime = responseTime + freshnessLifetime - currentAge</span></span>
<span class="line"><span></span></span>
<span class="line"><span>responseTime 浏览器接收响应时间</span></span>
<span class="line"><span>currentAge = currentTime - storeTime</span></span></code></pre></div><p>meta cache-control 不建议用，html4 标准，5 没有</p><p><a href="https://stackoverflow.com/questions/49547/how-do-we-control-web-page-caching-across-all-browsers" target="_blank" rel="noreferrer">http - How do we control web page caching, across all browsers? - Stack Overflow</a></p><h3 id="内存缓存" tabindex="-1">内存缓存 <a class="header-anchor" href="#内存缓存" aria-label="Permalink to &quot;内存缓存&quot;">​</a></h3><p>根据 HTTP 缓存控制头的设置，JavaScript 资源可以在浏览器内存缓存中存储的时间不同。如果资源的缓存策略设置为“no-cache”或“no-store”，则浏览器不会将资源缓存在内存中。如果资源的缓存策略设置为“max-age”或“expires”，则资源可以在浏览器内存缓存中存储一段时间，通常为几分钟到几个小时。</p><p>HTTP 响应头中的 age 和 max-age 是用于控制缓存的两个参数，它们有以下区别：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>age: 11430</span></span>
<span class="line"><span>alt-svc: quic=&quot;218.68.136.42:443&quot;; ma=300; v=&quot;44,43,39&quot;</span></span>
<span class="line"><span>content-encoding: br</span></span>
<span class="line"><span>content-md5: K4R9wAwG1m3bEjwhE8eZuQ==</span></span>
<span class="line"><span>content-type: application/javascript</span></span>
<span class="line"><span>date: Tue, 07 Mar 2023 10:23:00 GMT</span></span>
<span class="line"><span>etag: &quot;2b847dc00c06d66ddb123c2113c799b9&quot;</span></span>
<span class="line"><span>expires: Fri, 10 Mar 2023 07:06:09 GMT</span></span>
<span class="line"><span>last-modified: Tue, 07 Mar 2023 07:06:04 GMT</span></span></code></pre></div><p>以上信息中有 expires 字段，标记 3 天后失效？</p><p>age：表示 HTTP 响应从服务器发送到客户端的时间，即响应的年龄。当客户端收到响应后，会计算出 age 参数值，并与 max-age 进行比较，用于判断响应是否过期。</p><p>max-age：表示 HTTP 响应的最大缓存时间（以秒为单位），即客户端可以在这段时间内使用缓存的响应，而不需要向服务器发送新的请求。当客户端请求某个资源时，会先检查缓存中是否存在该资源，并计算出它的 age 值。如果 age 的值小于 max-age，则客户端可以使用缓存的响应，否则需要向服务器发送新的请求。</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>建立在 SSL/TLS 协议上，采用了公钥加密法，基本过程是：</p><ol><li>客户端向服务器端索要并验证公钥。</li><li>双方协商生成”会话密钥”。</li><li>双方采用”会话密钥”进行加密通信</li></ol><p>数据通信 对称加密 签名 非对称加密</p><p>SSL 握手 s =&gt; send pubkey =&gt; c c =&gt; 生成对称加密 session key ，并用 pubkey 加密 =&gt; s 用私钥解密 之后使用对称加密 key 数据传输</p><p><a href="https://www.quora.com/Does-SSL-and-TLS-use-asymmetric-encryption" target="_blank" rel="noreferrer">Does SSL and TLS use asymmetric encryption? - Quora</a></p><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>CORS 处理非简单请求（如 POST）会触发 options</p><p>Access-Control-Max-Age 指定 prelight 请求缓存多长时间，这个时间内不再需要发 <a href="https://blog.csdn.net/wanwan5856/article/details/79592681" target="_blank" rel="noreferrer">减少 options 请求次数 和 数据量大时前端渲染的处理 - wanwan5856 的博客 - CSDN 博客</a></p><p>简单请求的定义，来自 MDN，不是标准。简单请求要满足一系列条件，如仅使用 CORS 安全 请求头。而需要 prelight 的请求，意味着涉及用户数据</p><h2 id="返回状态码" tabindex="-1">返回状态码 <a class="header-anchor" href="#返回状态码" aria-label="Permalink to &quot;返回状态码&quot;">​</a></h2><p>助记：1-5 / I OR CS</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>1xx 信息 Information(I)</span></span>
<span class="line"><span>2xx 成功 OK(O)</span></span>
<span class="line"><span>3xx 重定向 Redirect(R)</span></span>
<span class="line"><span>4xx 客户端错误 Client Error(C)</span></span>
<span class="line"><span>5xx 服务端错误 Server Error(S)</span></span></code></pre></div><p>pragma 〔计〕杂注,编译指示</p><p>交换完连接即关闭，而长连接(HTTP1.1)只有在服务端收到<code>Connection: close</code>才会关闭</p><ul><li>206 - 大文件分块下载时使用 <code>curl --header &quot;Range: bytes=500-1000&quot; https://raw.githubusercontent.com/Germey/LaravelGeetest/master/README.md</code></li></ul><h2 id="get-与-post-区别" tabindex="-1">GET 与 POST 区别 <a class="header-anchor" href="#get-与-post-区别" aria-label="Permalink to &quot;GET 与 POST 区别&quot;">​</a></h2><ul><li>用途</li><li>参数形式</li><li>编码</li><li>安全性</li></ul><p>对于 GET 方式的请求，浏览器会把 http header 和 data 一并发送出去，服务器响应 200（返回数据）； 而对于 POST，浏览器先发送 header，服务器响应 100 continue，浏览器再发送 data，服务器响应 200 ok（返回数据）。</p><p>get 只读，cdn 缓存</p><p>post 副作用，需要 web 服务器操作</p><p>100 continue 并非 post 必然使用，使用场景是 post/put，发送大量数据场景的请求优化</p><p><a href="https://gms.tf/when-curl-sends-100-continue.html" target="_blank" rel="noreferrer">When curl sends 100-continue | Georg&#39;s Log</a><a href="https://www.zhihu.com/question/31640769" target="_blank" rel="noreferrer">post 相比get 有很多优点，为什么现在的HTTP通信中大多数请求还是使用get？ - 知乎</a></p><h3 id="get-url-长度限制" tabindex="-1">get url 长度限制 <a class="header-anchor" href="#get-url-长度限制" aria-label="Permalink to &quot;get url 长度限制&quot;">​</a></h3><p>服务器截断 8kb IE 2kb chrome 2MB firefox 不限制</p><p>实测，超过 10kb 可正常请求，地址栏显示省略号 超过 25kb 请求异常</p><h2 id="请描述-cookies、sessionstorage-和-localstorage-的区别" tabindex="-1">请描述 cookies、sessionStorage 和 localStorage 的区别? <a class="header-anchor" href="#请描述-cookies、sessionstorage-和-localstorage-的区别" aria-label="Permalink to &quot;请描述 cookies、sessionStorage 和 localStorage 的区别?&quot;">​</a></h2><ol><li>存储方式：cookies 存储在 http 信息的实体中，http 每次请求都会携带 cookie, cookie 在浏览器和服务器间来回传递， 后两者仅在本地保存</li><li>存储大小：cookie 数据不能超过 4k; 后两者要大很多，可以达到 5M</li><li>有效期：cookie 在设置的 cookie 有效期之前有效，即使浏览器或窗口关闭；sessionStorage 仅在当前浏览器窗口关闭前有效，不可持久保存；localSorage 始终有效，窗口或浏览器关闭也一直保存，可做持久数据</li><li>作用域：cookie、localStorage 在所有的同源窗口中都是共享的；sessionStorage 只能在当前页面使用</li></ol><p>sessionStorage</p><ul><li>刷新或恢复页面（重新打开关闭的标签页）时，session 存在</li><li>创建一个新的相同 URL 页面，会创建新的 session</li><li>试验 <a href="https://codesandbox.io/s/992th?file=/src/index.js" target="_blank" rel="noreferrer">https://codesandbox.io/s/992th?file=/src/index.js</a></li></ul><p>sessionStorage, localStorage 存储 size 限制 5MB，各浏览器一致，同步执行，可阻塞主线程 <a href="https://web.dev/storage-for-the-web/#check" target="_blank" rel="noreferrer">Storage for the web</a></p><h2 id="http-与-tcp-区别" tabindex="-1">http 与 tcp 区别 <a class="header-anchor" href="#http-与-tcp-区别" aria-label="Permalink to &quot;http 与 tcp 区别&quot;">​</a></h2><ul><li>tcp 是传输层，http 是跑在 tcp 上的应用层协议</li></ul><p><a href="https://www.infoq.cn/article/x80uOvcRyxVYw3KVusUm" target="_blank" rel="noreferrer">HTTP/3 的过去、现在和未来-InfoQ</a></p><h2 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h2><ol><li>浏览器 cache</li><li>操作系统 cache</li><li>路由器 cache</li><li>ISP 网络运营商 cache (以上递归查询 - dns 服务器)</li><li>root (以下 迭代查询)</li><li>域</li><li>权威解析服务器 - 返回 IP</li></ol><p>流程：解析-请求-渲染</p><p>递归查询-客户端查一次，迭代查询-客户端反复查 <a href="https://www.cnblogs.com/xiangsikai/p/8438601.html" target="_blank" rel="noreferrer">DNS 递归/迭代 原理 - kevin.Xiang - 博客园</a></p><p><a href="https://github.com/lgwebdream/FE-Interview/issues/14#issuecomment-647606369" target="_blank" rel="noreferrer">第 8 题：说一下 Http 缓存策略，有什么区别，分别解决了什么问题 · Issue #14 · lgwebdream/FE-Interview</a></p><p><a href="https://www.jianshu.com/p/54cc04190252" target="_blank" rel="noreferrer">深入理解浏览器的缓存机制 - 简书</a></p><h2 id="tcp" tabindex="-1">TCP <a class="header-anchor" href="#tcp" aria-label="Permalink to &quot;TCP&quot;">​</a></h2><p>TCP 三次握手，建立可靠连接，双边要同步(SYN)和确认(ACK)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>C -&gt; SYN -&gt; S</span></span>
<span class="line"><span>C &lt;- SYN-ACK &lt;- S</span></span>
<span class="line"><span>C -&gt; ACK -&gt; S</span></span></code></pre></div><p>序列号和确认号的使用允许双方检测丢失或乱序的数据片段</p><p><a href="https://www.google.com/search?q=tcp+handshake&amp;oq=tcp+handshake&amp;aqs=chrome..69i57.6609j0j7&amp;sourceid=chrome&amp;ie=UTF-8" target="_blank" rel="noreferrer">https://www.google.com/search?q=tcp+handshake&amp;oq=tcp+handshake&amp;aqs=chrome..69i57.6609j0j7&amp;sourceid=chrome&amp;ie=UTF-8</a></p><p>四次挥手 Finish</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>C -&gt; FIN -&gt; S</span></span>
<span class="line"><span>C &lt;- ACK &lt;- S</span></span>
<span class="line"><span>C &lt;- keep send and FIN &lt;- S</span></span>
<span class="line"><span>C -&gt; ACK -&gt; S</span></span></code></pre></div><p><a href="https://wiki.wireshark.org/TCP%25204-times%2520close" target="_blank" rel="noreferrer">TCP 4-times close - The Wireshark Wiki</a></p><h2 id="etag-和-last-modified-区别-使用场景" tabindex="-1">Etag 和 Last-Modified 区别，使用场景 <a class="header-anchor" href="#etag-和-last-modified-区别-使用场景" aria-label="Permalink to &quot;Etag 和 Last-Modified 区别，使用场景&quot;">​</a></h2><ul><li>优先级</li><li>准确性、及时性</li><li>场景</li></ul><blockquote><p>Etag nginx 是基于 Last-Modified 和 Content-Length 计算，更新更及时？</p></blockquote><h2 id="expires-和-cache-control" tabindex="-1">Expires 和 Cache-Control <a class="header-anchor" href="#expires-和-cache-control" aria-label="Permalink to &quot;Expires 和 Cache-Control&quot;">​</a></h2><p>Expires 要求客户端和服务端的时钟严格同步。 HTTP1.1 引入 Cache-Control来克服Expires头的限制。如果max-age和Expires同时出现，则 max-age 有更高的优先级。</p><p>Last-Modified 与 Etag 对比，精确度、分布式部署一致性、性能消耗、优先级 <a href="https://mp.weixin.qq.com/s?__biz=MzA4ODUzNTE2Nw==&amp;mid=2451060772&amp;idx=3&amp;sn=3ee0c658dd84a6e481bb3cc14e502a04&amp;chksm=87c42134b0b3a822122a78b3bb676d122c0fbcd280dc9facd0c19e7cbe4b638ab09b283c590d#rd" target="_blank" rel="noreferrer">通过 Node.js 小示例学习浏览器缓存策略</a></p><h2 id="加密" tabindex="-1">加密 <a class="header-anchor" href="#加密" aria-label="Permalink to &quot;加密&quot;">​</a></h2><p>HTTPS是对称加密还是非对称加密 HTTPS 在<strong>内容传输</strong>的加密上使用的是对称加密，非对称加密只作用在<strong>证书验证</strong>阶段。</p><h2 id="幂等性" tabindex="-1">幂等性 <a class="header-anchor" href="#幂等性" aria-label="Permalink to &quot;幂等性&quot;">​</a></h2><p>什么是幂等？一个操作如果具有任意多次执行所产生的影响均与一次执行的影响相同，我们就称之为幂等。</p><p>POST 不满足，多次调用创建多个</p><p>GET/PUT/DELETE 满足</p><p>幂等设计的作用是，允许客户端多次重试，而不产生意外副作用</p><h2 id="常用-code" tabindex="-1">常用 code <a class="header-anchor" href="#常用-code" aria-label="Permalink to &quot;常用 code&quot;">​</a></h2><p>304 命中协商缓存，客户端取本地缓存</p><p>403 Forbidden 服务端有能力处理，客户端 IP 被封禁</p><h2 id="form-urlencoded" tabindex="-1">form-urlencoded <a class="header-anchor" href="#form-urlencoded" aria-label="Permalink to &quot;form-urlencoded&quot;">​</a></h2><p>axios 默认将 JS 对象序列化成 JSON，保留原数据类型</p><p>form-urlencoded 将所有属性转成字符串，以单一块放到 body 中发出（与 body 搭配使用）</p><p><a href="https://axios-http.com/docs/urlencoded" target="_blank" rel="noreferrer">https://axios-http.com/docs/urlencoded</a></p><p>http get 也支持携带 body，各工具也支持，看请求是否携带 data 或 body 字样</p>`,97),o=[l];function i(r,p,c,h,d,g){return s(),e("div",null,o)}const f=a(n,[["render",i]]);export{m as __pageData,f as default};
